// Fixed public-only vectors generated by unmodified AgentPin 0.3.0 / p256 0.13.2.
// Do not regenerate with the new SDK: this is a cross-version wire-format test.
use agentpin::{
    crypto, jwk, jwt,
    pinning::{KeyPinStore, PinningResult},
};
#[test]
fn legacy_keys_jwt_and_pins_survive_crypto_upgrade() {
    let data: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/crypto-0.3.0.json")).unwrap();
    let pem = data["public_key_pem"].as_str().unwrap();
    let key: jwk::Jwk = serde_json::from_value(data["jwk"].clone()).unwrap();
    assert_eq!(jwk::jwk_to_pem(&key).unwrap(), pem);
    assert_eq!(jwk::pem_to_jwk(pem, "legacy-key").unwrap(), key);
    assert_eq!(
        crypto::generate_key_id(pem).unwrap(),
        data["key_id"].as_str().unwrap()
    );
    let vk = crypto::load_verifying_key(pem).unwrap();
    let token = data["jwt"].as_str().unwrap();
    let (_, payload) = jwt::verify_jwt(token, &vk).unwrap();
    assert_eq!(payload.iss, "example.com");
    assert!(jwt::verify_jwt(&token.replace("eyJpc3Mi", "eyJqc3Mi"), &vk).is_err());
    let mut pins = KeyPinStore::from_json(&data["pins"].to_string()).unwrap();
    assert_eq!(
        pins.check_and_pin("example.com", &key),
        PinningResult::Matched
    );
    let wrong = crypto::generate_key_pair().unwrap();
    let wrong = crypto::load_verifying_key(&wrong.public_key_pem).unwrap();
    assert!(jwt::verify_jwt(token, &wrong).is_err());
}
